package ru.ilya.alitahome;
import android.app.*;import android.content.*;import android.graphics.*;import android.graphics.drawable.*;import android.provider.Settings;import android.view.*;import android.view.animation.PathInterpolator;import android.widget.*;
/** Design tokens from the supplied VladOS prototype; sizes are already in dp/sp. */
final class VladDesign {
 static final int VOID=0xff050508,INK=0xff0b0a13,GLASS=0xa8181528,GLASS_HI=0xb82c2648,LINE=0x21c4b8ff,TEXT=0xfff2f1f8,MUTE=0xffa19db8,DIM=0xff615d78,ICON=0xffdad8e6,VIOLET=0xff8b4dff,VIOLET_HI=0xffb18bff,OK=0xff5bd69b,BAD=0xffff6b8a;
 static final int SAFE=60,CARD_W=198,CARD_H=112,TILE=100,GAP=15,RADIUS=11;
 static Typeface body,display;
 static int dp(Context c,float value){return Math.round(c.getResources().getDisplayMetrics().density*value);}
 static void fonts(Context c){if(body==null){body=Typeface.createFromAsset(c.getAssets(),"fonts/onest.ttf");display=Typeface.createFromAsset(c.getAssets(),"fonts/unbounded.ttf");}}
 static TextView text(Context c,String value,float size,int color){fonts(c);TextView t=new TextView(c);t.setText(value);t.setTextColor(color);t.setTextSize(size);t.setTypeface(body);t.setIncludeFontPadding(false);return t;}
 static TextView display(Context c,String value,float size,int weight){TextView t=text(c,value,size,TEXT);t.setTypeface(display);if(android.os.Build.VERSION.SDK_INT>=26)t.setFontVariationSettings("'wght' "+weight);return t;}
 static GradientDrawable shape(Context c,int color,float radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(c,radius));return d;}
 static boolean motion(Context c){return c.getSharedPreferences("home",0).getBoolean("motion",true)&&Settings.Global.getFloat(c.getContentResolver(),Settings.Global.ANIMATOR_DURATION_SCALE,1)>0;}
 static Drawable resource(Context c,String name){int id=c.getResources().getIdentifier(name,"drawable",c.getPackageName());return id==0?new android.graphics.drawable.ColorDrawable(android.graphics.Color.TRANSPARENT):c.getDrawable(id);}
 static Drawable icon(Context c,String name,boolean focus){Drawable base=resource(c,"red_"+name+"_base").mutate(),accent=resource(c,"red_"+name+"_accent").mutate();if(c.getResources().getIdentifier("red_"+name+"_base","drawable",c.getPackageName())==0)return resource(c,"red_"+name);base.setTint(focus?INK:ICON);accent.setTint(focus?VIOLET:VIOLET_HI);return new LayerDrawable(new Drawable[]{base,accent});}
 static ImageView iconView(Context c,String name,int size){ImageView image=new ImageView(c);image.setImageDrawable(icon(c,name,false));image.setScaleType(ImageView.ScaleType.FIT_CENTER);return image;}
  static void touch(View view){final android.os.Handler handler=new android.os.Handler();final boolean[] longer={false};final Runnable hold=()->{if(view.isLongClickable())longer[0]=view.performLongClick();};view.setOnTouchListener((v,e)->{if(e.getActionMasked()==MotionEvent.ACTION_DOWN){longer[0]=false;v.requestFocus();v.setPressed(true);handler.postDelayed(hold,ViewConfiguration.getLongPressTimeout());return true;}if(e.getActionMasked()==MotionEvent.ACTION_UP){handler.removeCallbacks(hold);v.setPressed(false);if(!longer[0])v.performClick();return true;}if(e.getActionMasked()==MotionEvent.ACTION_CANCEL){handler.removeCallbacks(hold);v.setPressed(false);return true;}return true;});}
 static void focus(Context c,View view,int mode){touch(view);view.setFocusable(true);view.setFocusableInTouchMode(true);view.setClickable(true);view.setOnFocusChangeListener((v,on)->{
  if(mode==1){GradientDrawable border=shape(c,android.graphics.Color.TRANSPARENT,RADIUS);if(on)border.setStroke(dp(c,2.5f),TEXT);v.setForeground(border);v.setElevation(on?dp(c,10):0);}
  else if(mode==2){GradientDrawable bg=shape(c,on?GLASS_HI:GLASS,RADIUS);if(on)bg.setStroke(dp(c,2),TEXT);v.setBackground(bg);}
  else {boolean tab=v.getTag() instanceof String&&((String)v.getTag()).startsWith("tab:");v.setBackground(shape(c,on?TEXT:tab?android.graphics.Color.TRANSPARENT:GLASS_HI,24));if(v instanceof TextView){((TextView)v).setTextColor(on?INK:TEXT);Object key=v.getTag(c.getResources().getIdentifier("vlad_icon_tag","id",c.getPackageName()));if(key instanceof String){Drawable d=icon(c,(String)key,on);d.setBounds(0,0,dp(c,15),dp(c,15));((TextView)v).setCompoundDrawables(d,null,null,null);}else{for(Drawable d:((TextView)v).getCompoundDrawables())if(d!=null)d.mutate().setTint(on?INK:ICON);}}}
  float scale=on?(mode==1?1.08f:mode==2?1.025f:1.04f):1;v.animate().cancel();if(motion(c))v.animate().scaleX(scale).scaleY(scale).setDuration(230).setInterpolator(new PathInterpolator(.2f,.8f,.2f,1)).start();else{v.setScaleX(scale);v.setScaleY(scale);}if(on){if(v.getParent() instanceof ViewGroup)((ViewGroup)v.getParent()).setClipChildren(false);}
 });}
 static TextView button(Context c,String label,String icon,Runnable action){TextView t=text(c,label,13,TEXT);t.setGravity(Gravity.CENTER);t.setPadding(dp(c,15),0,dp(c,15),0);t.setContentDescription(label);t.setBackground(shape(c,GLASS_HI,24));if(icon!=null){Drawable d=icon(c,icon,false);d.setBounds(0,0,dp(c,15),dp(c,15));t.setCompoundDrawables(d,null,null,null);t.setCompoundDrawablePadding(dp(c,8));t.setTag(c.getResources().getIdentifier("vlad_icon_tag","id",c.getPackageName()),icon);}focus(c,t,0);t.setOnClickListener(v->action.run());return t;}
 static FrameLayout background(Activity activity,boolean blurred){FrameLayout root=new FrameLayout(activity);root.setBackgroundColor(INK);ImageView wall=new ImageView(activity);wall.setScaleType(ImageView.ScaleType.CENTER_CROP);wall.setImageDrawable(resource(activity,blurred?"wallpaper_home_blur":"wallpaper_home_1080"));root.addView(wall,new FrameLayout.LayoutParams(-1,-1));View shade=new View(activity);shade.setBackground(new GradientDrawable(GradientDrawable.Orientation.LEFT_RIGHT,new int[]{0xd20b0a13,0x590b0a13,0x000b0a13}));root.addView(shade,new FrameLayout.LayoutParams(-1,-1));View bottom=new View(activity);bottom.setBackground(new GradientDrawable(GradientDrawable.Orientation.BOTTOM_TOP,new int[]{0xe60b0a13,0x000b0a13,0x000b0a13}));root.addView(bottom,new FrameLayout.LayoutParams(-1,-1));return root;}
 static LinearLayout column(Context c){LinearLayout l=new LinearLayout(c);l.setOrientation(1);l.setClipChildren(false);l.setClipToPadding(false);return l;}
 static void gap(Context c,LinearLayout parent,int value){parent.addView(new View(c),new LinearLayout.LayoutParams(1,dp(c,value)));}
 static void hints(Context c,FrameLayout root,boolean back){TextView t=text(c,"◀ ▲ ▼ ▶   Перемещение       OK   Открыть"+(back?"       ↩   Назад":""),10.5f,DIM);t.setGravity(Gravity.CENTER_VERTICAL);t.setPadding(dp(c,SAFE),0,0,0);t.setBackground(new GradientDrawable(GradientDrawable.Orientation.TOP_BOTTOM,new int[]{0x000b0a13,INK}));FrameLayout.LayoutParams p=new FrameLayout.LayoutParams(-1,dp(c,29),Gravity.BOTTOM);root.addView(t,p);}
 static final class Ring extends FrameLayout {
  final Context c;final String key;final Paint p=new Paint(3);boolean selected,active;long start;final TextView label,sub;
  Ring(Context context,String icon,String title,String subtitle,Runnable action){super(context);c=context;key=icon;setWillNotDraw(false);setClipChildren(false);label=text(c,title,11,MUTE);label.setSingleLine(true);label.setGravity(Gravity.CENTER);sub=text(c,subtitle,9.5f,DIM);sub.setGravity(Gravity.CENTER);ImageView image=iconView(c,icon,31);FrameLayout.LayoutParams ip=new FrameLayout.LayoutParams(dp(c,31),dp(c,31),Gravity.TOP|Gravity.CENTER_HORIZONTAL);ip.topMargin=dp(c,22);addView(image,ip);FrameLayout.LayoutParams lp=new FrameLayout.LayoutParams(-1,dp(c,16));lp.topMargin=dp(c,82);addView(label,lp);FrameLayout.LayoutParams sp=new FrameLayout.LayoutParams(-1,dp(c,14));sp.topMargin=dp(c,99);addView(sub,sp);setContentDescription(title);setFocusable(true);setFocusableInTouchMode(true);setClickable(true);touch(this);setOnClickListener(v->action.run());setOnFocusChangeListener((v,on)->{selected=on;start=System.currentTimeMillis();label.setTextColor(on?TEXT:MUTE);float scale=on?1.1f:1;animate().scaleX(scale).scaleY(scale).setDuration(motion(c)?240:0).start();invalidate();});}
  void setActive(boolean value){if(active!=value){active=value;invalidate();}}
  @Override protected void onDraw(Canvas canvas){super.onDraw(canvas);float cx=getWidth()/2f,cy=dp(c,37),r=dp(c,35);p.setShader(null);p.setStyle(Paint.Style.FILL);p.setColor(selected?GLASS_HI:GLASS);canvas.drawCircle(cx,cy,r,p);canvas.save();if(selected&&motion(c)){canvas.rotate((System.currentTimeMillis()-start)%6000*360f/6000,cx,cy);postInvalidateDelayed(32);}p.setStyle(Paint.Style.STROKE);p.setStrokeCap(Paint.Cap.ROUND);p.setStrokeWidth(dp(c,1.75f));RectF oval=new RectF(cx-r,cy-r,cx+r,cy+r);p.setColor(selected?TEXT:0x6be1def0);canvas.drawArc(oval,-178,150,false,p);p.setColor(active?OK:VIOLET);canvas.drawArc(oval,30,118,false,p);canvas.restore();}
 }
}